INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('chinnar', 2, 5, 'go',
  'Driest, sharpest. 16-30C. Trail conditions at year-firmest. Wildlife concentrating at remaining waterholes.',
  'February is the cleanest of the cool rain-shadow months — rainfall under 10mm, sanctuary tracks at year-firmest, wildlife concentration at the few remaining waterholes climbs sharply. Thoovanam Falls trek (7km, 4-5 hours) at peak photographic value — falls still flowing, trail dry.',
  NULL,
  'Chinnar in February is the technical sweet spot. Rainfall averages under 10mm, daytime 19-30C in the dry deciduous zone, nights 16-18C. The 90 sq km sanctuary in the Western Ghats rain-shadow has its remaining waterholes concentrated at year-firmest — wildlife sighting odds peak. The endangered Grizzled Giant Squirrel (Ratufa macroura, Chinnar''s flagship species, only Indian habitat, population 280-330) hits year-best detection probability in the dry deciduous trees along the Thoovanam trail. Star tortoise, mugger crocodile (Pampar river crossings), spotted deer, sambar, gaur, sloth bear all concentrate visibly. The Forest Department escorted Thoovanam Falls trek (7km, 4-5 hours moderate, ₹500-1,000 group rate) from the Marayoor range office hits its peak operational month — falls still flowing post-NE-monsoon-residual, trail at year-firmest. 225+ recorded bird species at high detection. Stays at Marayoor (12km from sanctuary, sandalwood town) homestays ₹1,000-2,200, plantation cottages ₹2,500-4,500; Munnar (60km on NH85) holds the broader bracket ₹2,000-22,000 (rates 25 percent below January peak). Sandalwood Reserve at Marayoor (Forest Department-managed, ₹50 entry) at peak photogenic. Online booking lead at the Kerala Forest Department portal: 24-48 hours sufficient.'
)
