INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('chinnar', 6, 1, 'skip',
  'SW monsoon weak in rain-shadow. 24-32C, 100-150mm rainfall. Trails workable but heat residual. Skip.',
  NULL,
  'June is monsoon-weak in the rain-shadow zone — only 100-150mm rainfall versus 800-1000mm at Munnar. Thoovanam Falls flow returns slowly. Heat residual makes trails uncomfortable. Wait for November.',
  'Chinnar in June carries the unique paradox of being a Western Ghats monsoon-shadow zone. Rainfall hits only 100-150mm at the 90 sq km sanctuary across 8-12 wet days — versus 600-800mm at Munnar 60km west, the lowest monsoon impact of any Kerala Western Ghats sanctuary. Daytime 26-32C in the dry deciduous tracks, nights 24-26C, humidity climbing toward 70 percent. The 7km Thoovanam Falls trek (4-5 hours moderate) remains operationally workable but the residual heat makes mid-day walks uncomfortable; Kerala Forest Department keeps dawn-only slot restrictions for safety. Falls flow begins recovering — Thoovanam reaches 1/3 of peak January discharge by month-end. Wildlife disperses as monsoon-fed water sources reach across the sanctuary; the dry-season concentration at remaining waterholes ends. Grizzled Giant Squirrel (Ratufa macroura) sightings drop to 4-6 per trek versus the dry-season 10-12. Marayoor Sandalwood Reserve workable mornings only. Stays at year-low rates outside the rare festival weekend. NH85 (Kochi-Munnar-Marayoor 200km) becomes landslide-watch country in the Munnar belt; the Marayoor approach is more weather-stable but transit gets compromised. Wait for November.'
)
