INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('chinnar', 8, 1, 'skip',
  'Rain-shadow monsoon continues. 23-30C, 100-150mm rainfall. Wildlife dispersed. Onam closes Marayoor. Skip.',
  NULL,
  'August holds the July pattern in the rain-shadow zone — 100-150mm rainfall, wildlife dispersed, NH85 Kochi-Munnar-Marayoor unreliable. Onam closes most operations 3-4 days. Wait for November.',
  'Chinnar in August holds the July rain-shadow monsoon pattern with marginally less rain. Rainfall 100-150mm at the 90 sq km sanctuary across 8-12 wet days. Daytime 24-30C in the dry deciduous zone, nights 23-24C, humidity 75 percent. The 7km Thoovanam Falls trek (4-5 hours moderate) remains operationally workable through the Kerala Forest Department Marayoor range office, online booking at the Forest Department portal — but wildlife sighting probability stays at year-low as water sources abundance keeps animals dispersed. Grizzled Giant Squirrel (Ratufa macroura, only Indian habitat, population 280-330) visibility 3-5 per trek versus 10-12 dry-season peak. NH85 Kochi-Munnar-Marayoor (200km) closure events continue 1-2 per week through the Munnar belt. Onam — Kerala''s 10-day cultural festival running Atham to Thiruvonam (variable date late August into September) — closes most Marayoor and Munnar shops, restaurants, and resort activities for 3-4 days around Thiruvonam. Marayoor Sandalwood Reserve (₹50 entry, Forest Department-managed) at full hours outside Onam. Falls flow recovers further — Thoovanam approaches 2/3 of peak January discharge by month-end. Stays at year-low rates: homestays ₹600-1,400, plantation cottages ₹1,500-3,000. Wait for November.'
)
