INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('chinnar', 10, 2, 'wait',
  'NE monsoon hits TN border. 22-30C, 200-300mm rainfall. Falls strong, but rare-rain disruption to trek slots.',
  'October is when the northeast monsoon hits Tamil Nadu border zones — rainfall 200-300mm in the rain-shadow Chinnar zone, more than at Munnar. Trek slots disrupted on heavy days. Falls flow strong but wildlife dispersed. November is materially cleaner.',
  'October flips the rain-shadow paradox — the northeast monsoon delivers more rain to Chinnar than the southwest monsoon did, since the Tamil Nadu border catches retreating-monsoon flow. 200-300mm across 10-12 wet days disrupts trek operations on heavy afternoons. November is dramatically cleaner.',
  'Chinnar in October flips the rain-shadow paradox. The northeast monsoon — which dumps on Tamil Nadu and the eastern Kerala border zones — brings more rain to Chinnar than the southwest monsoon did. Rainfall 200-300mm across 10-12 wet days, mostly afternoon thunderstorms. Daytime 23-30C in the dry deciduous zone, nights 22-24C, humidity 75 percent. The 7km Thoovanam Falls trek (4-5 hours moderate, ₹500-1,000 group rate) operates at full Kerala Forest Department schedule from the Marayoor range office but slots disrupt on heavy-rain afternoons — same-day check at the Forest Department portal recommended. Falls flow strong as catchment refills from NE monsoon. Wildlife remains dispersed — Grizzled Giant Squirrel (Ratufa macroura, only Indian habitat, population 280-330) visibility 4-6 per trek, gaur and sloth bear odds 50 percent of dry-season peak. Marayoor Sandalwood Reserve (₹50 entry) at full hours. Stays at Marayoor homestays ₹800-1,800, plantation cottages ₹2,000-4,000; Munnar bracket (60km) ₹1,500-18,000 (rates 30 percent below December peak). NH85 Kochi-Munnar-Marayoor (200km) at year-clearest visibility through the Munnar belt by mid-month. November is materially cleaner with one-month patience.'
)
